}

func divide(a, b float64) (float64, error) {
	if b == 0 {
		return 0, fmt.Errorf("divide by zero")
	}
	return a / b, nil
}

r, err := divide(6, 3)
if err != nil {
	fmt.Println(err)
	return
}
fmt.Println(r)

func sum(nums ...int) int {
	t := 0
	for _, n := range nums {
		t += n
	}
	return t
}

counter := func() func() int {
	c := 0
	return func() int { c++; return c }
}()
fmt.Println(sum(1, 2, 3), counter(), counter())

